package matteroverdrive.network;
import matteroverdrive.blockentity.StarMapBlockEntity;import matteroverdrive.menu.StarMapMenu;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkEvent;import java.util.function.Supplier;
public record StarMapFleetAttackPacket(BlockPos mapPos){public static void encode(StarMapFleetAttackPacket p,FriendlyByteBuf b){b.writeBlockPos(p.mapPos);}public static StarMapFleetAttackPacket decode(FriendlyByteBuf b){return new StarMapFleetAttackPacket(b.readBlockPos());}public static void handle(StarMapFleetAttackPacket p,Supplier<NetworkEvent.Context> s){NetworkEvent.Context c=s.get();ServerPlayer sender=c.getSender();if(sender!=null)c.enqueueWork(()->{if(!(sender.containerMenu instanceof StarMapMenu menu)||!menu.mapPos().equals(p.mapPos))return;if(sender.distanceToSqr(p.mapPos.getX()+.5,p.mapPos.getY()+.5,p.mapPos.getZ()+.5)>64)return;if(sender.level().getBlockEntity(p.mapPos) instanceof StarMapBlockEntity map)map.requestFleetAttack(sender);});c.setPacketHandled(true);}}
